def solution(input_str):
    line = input_str.strip()
    n, x = map(int, line.split())

    if n == 1:
        return '-1\n'

    # Find all divisors of n
    divisors = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divisors.append(i)
            if i * i != n:
                divisors.append(n // i)

    # For each divisor d of n, we need a prime p such that p-1 = d
    # Then b ≡ 1 (mod d), so largest b < x is x-1 if (x-1) % d == 1, else x-1 - (something)

    max_b = -1

    for d in divisors:
        # We need prime p = d + 1
        p = d + 1
        if p > 2:
            # Check if p is prime
            is_prime = True
            if p < 2:
                is_prime = False
            elif p == 2:
                pass
            else:
                for i in range(2, int(math.sqrt(p)) + 1):
                    if p % i == 0:
                        is_prime = False
                        break
        else:
            is_prime = p == 2

        if is_prime:
            # We can use b ≡ 1 (mod d)
            # Find largest b < x where b % d == 1
            if x - 1 >= 1:
                b = (x - 2) // d * d + 1
                if b < 1:
                    b += d
                if b < x and b > 1:
                    max_b = max(max_b, b)

    return str(max_b) + '\n' if max_b != -1 else '-1\n'
