    # Fenwick Tree
    class FenwickTree:
        def __init__(self, size):
            self.tree = [0] * (size + 1)

        def update(self, i, delta):
            while i < len(self.tree):
                self.tree[i] += delta
                i += i & (-i)

        def query(self, i):
            if i < 1:
                return 0
            while i > 0:
                self.tree[i] = self.tree[i]
