def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    coords = [tuple(map(int, line.split())) for line in lines[1:n+1]]

    MOD = 1000000007

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def is_valid_triangle(i, k, j):
        cp = cross_product(coords[i], coords[k], coords[j])
        if cp == 0:
            return False

        if cp < 0:
            for m in range(i + 1, k):
                if cross_product(coords[i], coords[k], coords[m]) * cp >= 0:
                    return False
            for m in range(k + 1, j):
                if cross_product(coords[k], coords[j], coords[m]) * cp >= 0:
                    return False
        else:
            for m in range(i + 1, k):
                if cross_product(coords[i], coords[k], coords[m]) * cp <= 0:
                    return False
            for m in range(k + 1, j):
                if cross_product(coords[k], coords[j], coords[m]) * cp <= 0:
                    return False

        return True

    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i+1] = 1

    for length in range(2, n):
        for i in range(n - length):
            j = i + length
            for k in range(i + 1, j):
                if is_valid_triangle(i, k, j):
                    dp[i][j] = (dp[i][j] + dp[i][k] * dp[k][j]) % MOD

    return str(dp[0][n - 1])
