Looking at this problem, I need to:
1. Understand the shuffle structure (digits of n + decimal representation of k where k = length of n)
2. Find the smallest valid n that contains the given substring
3. Reconstruct n from the remaining digits after accounting for k

Let me work through the solution:

```python
from collections import Counter

def solution(input_str):
    lines = input_str.strip().split('\n')
    shuffled = lines[0]
    substring = lines[1]

    digit_count = Counter(shuffled)
    L = len(shuffled)
    sub_count = Counter(substring)
    sub_len = len(substring)

    def build_n(rem, sub_pos):
        """Given remaining digits and position to insert substring, build smallest n"""
        other_digits = []
        for d in sorted(rem.keys()):
            other_digits.extend([str(d)] * rem[d])

        result = other_digits[:sub_pos] + list(substring) + other_digits[sub_pos:]
        return ''.join(result)

    def validate(n_str, origin_digit_count):
        """Verify if n_str can be formed from available digits"""
        n_count = Counter(n_str)
        for d in n_count:
            if n_count[d] > origin_digit_count.get(d, 0):
                return False
        return True

    for k in range(1, L):
        k_str = str(k)
        if k + len(k_str) != L:
            continue

        # Check if we have digits for k
        k_count = Counter(k_str)
        if any(digit_count[d] < k_count[d] for d in k_count):
            continue

        # Remove k's digits from pool
        remaining = digit_count.copy()
        for d in k_count:
            remaining[d] -= k_count[d]

        # Check if we can form substring from remaining
        can_form_sub = all(remaining.get(d, 0) >= cnt for d, cnt in sub_count.items())
        if not can_form_sub:
            continue

        # Try different positions for the substring
        other_digits = []
        for d in sorted(remaining.keys()):
            other_digits.extend([str(d)] * remaining[d])

        for sub_pos in range(len(other_digits) + 1):
            n_str = other_digits[:sub_pos] + list(substring) + other_digits[sub_pos:]
            n_str = ''.join(n_str)

            if len(n_str) != k:
                continue

            # No leading zeros unless n is just "0"
            if len(n_str) > 1 and n_str[0] == '0':
                continue

            if validate(n_str, remaining):
                return n_str

    # Fallback: try using all remaining digits in sorted order
    other_digits = []
    for d in sorted(digit_count.keys()):
        other_digits.extend([str(d)] * digit_count[d])
    other_digits.pop(0)  # Remove first digit

    # Adjust for leading zeros
    if other_digits[0] == '0' and len(other_digits) > 1:
        # Find first non-zero digit
        for d in other_digits[1:]:
            if d != '0':
                idx = other_digits.index(d)
                other_digits.insert(0, other_digits[idx])
                del other_digits[idx+1]
                break

    return ''.join(other_digits)


