            other_digits.extend([str(d)] * remaining[d])

        for sub_pos in range(len(other_digits) + 1):
            n_chars = other_digits[:sub_pos] + list(substring) + other_digits[sub_pos:]
            n_str = ''.join(n_chars)

            if len(n_str) != k:
                continue

            if len(n_str) > 1 and n_str[0] == '0':
                continue

            n_count = Counter(n_str)
            valid = True
            for d in n_count:
                if n_count.get(d, 0) > remaining.get(d, 0):
                    valid = False
                    break
            if valid:
                return n_str

    other = []
    for d in sorted(digit_count.keys()):
        other.extend([str(d)] * digit_count[d])

    if len(other) > 1 and other[0] == '0':
        for i, c in enumerate(other[1:], 1):
            if c != '0':
                other.insert(0, other[i])
                other.pop(i)
                break

    return ''.join(other)
